CREATE TABLE knowledge_graph_extraction_batches (id varchar(64) PRIMARY KEY, tenant_id varchar(64) NOT NULL, source_revision_id varchar(64) NOT NULL, source_sha256 varchar(64) NOT NULL CHECK(length(source_sha256)=64), course_id varchar(64), state varchar(24) NOT NULL CHECK(state IN ('draft','in_review','accepted','rejected')), created_by varchar(64) NOT NULL, reviewed_by varchar(64), candidate_count integer NOT NULL CHECK(candidate_count>=0), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE INDEX ix_kg_extract_batch_tenant_state ON knowledge_graph_extraction_batches(tenant_id,state);
CREATE INDEX ix_kg_extract_batch_source ON knowledge_graph_extraction_batches(tenant_id,source_revision_id);
CREATE TABLE knowledge_graph_extraction_candidates (id varchar(64) PRIMARY KEY, batch_id varchar(64) NOT NULL REFERENCES knowledge_graph_extraction_batches(id) ON DELETE CASCADE, tenant_id varchar(64) NOT NULL, candidate_type varchar(24) NOT NULL CHECK(candidate_type IN ('node','relation')), label varchar(300) NOT NULL DEFAULT '', source_label varchar(300), target_label varchar(300), kind varchar(32) NOT NULL, rationale text NOT NULL DEFAULT '', source_locator varchar(255) NOT NULL, confidence integer NOT NULL CHECK(confidence BETWEEN 0 AND 100), fingerprint varchar(64) NOT NULL, state varchar(24) NOT NULL CHECK(state IN ('draft','in_review','accepted','rejected')), created_node_id varchar(64), created_relation_id varchar(64), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE UNIQUE INDEX uq_kg_extract_fingerprint_batch ON knowledge_graph_extraction_candidates(batch_id,fingerprint);
CREATE INDEX ix_kg_extract_candidate_review ON knowledge_graph_extraction_candidates(tenant_id,state,confidence DESC);
